from pathlib import Path
base=Path('LaTeXBookCode/src/chapters'); log=Path('work/editorial-2026-09-05/editor-6-10.md')
def replace(f,a,b,why):
 p=base/(f+'.tex');s=p.read_text();assert a in s,(f,a[:80]);s=s.replace(a,b);p.write_text(s)
 with log.open('a') as o:o.write('\n\n### Follow-up '+f+'\nReason: '+why+'\nBefore: '+a+'\nAfter: '+b)
def para(f,start,b,why):
 s=(base/(f+'.tex')).read_text();a=s.index(start);z=s.find('\n\n',a);replace(f,s[a:z],b,why)
